import{_ as l,l as t,o as e,c as o,v as n,p as u,x as r,d as p,i as P,S as s}from"./chunks/framework.InCnrqk-.js";const h=JSON.parse('{"title":"Vera Rubin NVL72 平台","description":"","frontmatter":{"title":"Vera Rubin NVL72 平台","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vera-rubin-platform.md","filePath":"llm/vera-rubin-platform.md","lastUpdated":1789023840000}'),V={name:"llm/vera-rubin-platform.md"};function c(N,a,d,m,A,L){const i=t("Mermaid");return e(),o("div",null,[a[1]||(a[1]=n('<h1 id="vera-rubin-nvl72-平台" tabindex="-1">Vera Rubin NVL72 平台 <a class="header-anchor" href="#vera-rubin-nvl72-平台" aria-label="Permalink to &quot;Vera Rubin NVL72 平台&quot;">​</a></h1><div class="epigraph"><p>NVL72 机柜是 Scale-Up 单元；Vera Rubin 平台把机柜、柜外网、存储与安全栈收成可复制的 AI 工厂产品，而不是只换一颗更快的 GPU。</p><footer>—— NVIDIA 对 Vera Rubin 平台的公开命题：six new chips, one AI supercomputer；NVL72 产品形态见机柜材料</footer></div><p><a href="/llm/vera-rubin-nvl72">Vera Rubin NVL72</a> 已经把「72 GPU + 36 CPU、NVLink 6 一块机柜加速器」写成编程与调度单位。<a href="/llm/rubin-six-chips">六芯片共设计</a> 写了 Rubin GPU、Vera CPU、NVLink 6 交换、ConnectX-9、BlueField-4、Spectrum-6 的分工。本篇把镜头拉到 <strong>平台</strong>：这些机柜如何经 Quantum-X800 InfiniBand 或 Spectrum-X 以太网组成集群、与存储 / 安全 / 后训练流水如何咬合，以及 2026 年公开材料里「七芯片、多机柜 POD」相对六芯片叙事多了什么。不整篇重复「逻辑加速器」论证，不把 Groq LPU 的规格抄进 72 的 GPU 计数，也不把厂商「相对 Blackwell 少用若干 GPU / 每 token 成本」写成自己的测量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只买一柜 NVL72，得到的是域内 TP / 宽 EP / 长 KV。预训练数据、多副本高可用、跨地域、检查点、多租户隔离，仍然要柜外网络与基础设施处理器。若平台被理解成「GPU SKU 升级」，网卡、DPU、以太网交换会按上一世代的过订阅与拥塞语义去配，MoE 的同步突发会在 Scale-Out 上先打满。平台要回答的是：Scale-Up 域的边界在哪、Scale-Out 的端点与交换是否与这一代 GPU 共设计、控制面与数据面如何隔离。</p><p>另一问是产品时间线。早期技术博客写六芯片共设计；2026 年 GTC / 新闻稿把 <strong>Groq 3 LPU</strong> 列为第七颗、并讨论多种专用机柜（计算 NVL72、以太网、存储、LPU）组成更大的 POD。规划时必须分清：哪些语句描述 NVL72 计算柜，哪些描述工厂级 POD。混写会导致把 256 LPU 或存储柜的能力算进 72 GPU 的 HBM。</p><h3 id="计算柜仍是-72-36-平台大于计算柜" tabindex="-1">计算柜仍是 72 + 36，平台大于计算柜 <a class="header-anchor" href="#计算柜仍是-72-36-平台大于计算柜" aria-label="Permalink to &quot;计算柜仍是 72 + 36，平台大于计算柜&quot;">​</a></h3><p>公开 NVL72 集成：72 个 Rubin GPU、36 个 Vera CPU、NVLink 6、ConnectX-9 SuperNIC、BlueField-4 DPU。柜外扩展写明 Quantum-X800 InfiniBand 或 Spectrum-X 以太网，以便多柜维持高利用率。平台级材料把 Spectrum-6 交换、共封装光学以太网、以及 DPU 上的存储与安全卸载算进同一代 BOM。程序员看见的仍是 CUDA device 与 RDMA 网卡；平台工程师看见的是两张网——柜内 NVLink、柜外 IB/以太——加上 DPU 上的基础设施平面。</p><p><span class="marginnote">新闻稿中的训练 GPU 倍数、推理每瓦吞吐、每 token 成本依赖指定 MoE 与精度，属于厂商声明。容量规划用：72 卡一域、柜外网卡存在、液冷柜级维护。带宽与端口数以当时产品页为准，本篇不复制整张会过期的规格表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把作业画在两层网上。域内：一份模型并行组，TP / EP / 域内集合通信走 NVLink 6 交换托盘，可卸部分归约到 SHARP。域外：数据并行、跨柜流水、多柜 MoE、检查点、拉取训练数据，走 ConnectX-9 注入、Spectrum-X 或 Quantum-X800 交换。禁止把跨柜 GPU 塞进同一 TP 组；编排系统应暴露「NVL 域」标签。这与机柜篇一致，平台篇补的是：<strong>多柜 SuperPOD / 工厂</strong>如何把许多 NVL72 当成可扩展单元，而不是把 72 再乘成一张更大的 NVLink 网——公开蓝图从未把 NVLink 域跨出机柜。</p><p>安全与多租户落在 BlueField-4 与 DOCA：新闻稿写机柜级机密计算、互连加密与证明、软件定义网络与租户隔离。训练作业不应在 Vera CPU 上与存储中断抢核；存储路径（包括后来公开的 STX 一类上下文 / KV 存储机柜）走 DPU 与专用架，避免检查点流量打 NVLink。CUDA 向后兼容被写成平台约束：旧核可跑，要吃新互连与窄精度仍需框架版本跟上。</p>',12)),(e(),u(s,null,{default:r(()=>[P(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20plat%5B%22Vera%20Rubin%20%E5%B9%B3%E5%8F%B0%22%5D%0A%20%20%20%20NVL%5B%22NVL72%20%E8%AE%A1%E7%AE%97%E6%9F%9C%3A%20NVLink%206%20%E5%9F%9F%22%5D%0A%20%20%20%20NIC%5B%22ConnectX-9%20%E2%86%92%20Quantum-X800%20%2F%20Spectrum-X%22%5D%0A%20%20%20%20DPU%5B%22BlueField-4%3A%20%E5%AD%98%E5%82%A8%20%2F%20%E5%AE%89%E5%85%A8%20%2F%20%E9%9A%94%E7%A6%BB%22%5D%0A%20%20%20%20NVL%20--%3E%20NIC%0A%20%20%20%20DPU%20--%3E%20NIC%0A%20%20end%0A%20%20NVL%20--%3E%20JOB%5B%22%E5%9F%9F%E5%86%85%3A%20%E4%B8%80%E4%BB%BD%E5%A4%A7%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20NIC%20--%3E%20CL%5B%22%E5%A4%9A%E6%9F%9C%3A%20DP%20%C2%B7%20%E6%A3%80%E6%9F%A5%E7%82%B9%20%C2%B7%20%E5%A4%9A%E5%89%AF%E6%9C%AC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h3 id="从六芯片到七芯片、从一柜到-pod" tabindex="-1">从六芯片到七芯片、从一柜到 POD <a class="header-anchor" href="#从六芯片到七芯片、从一柜到-pod" aria-label="Permalink to &quot;从六芯片到七芯片、从一柜到 POD&quot;">​</a></h3><p>六芯片合同没有过时：计算、编排、Scale-Up 交换、Scale-Out 端点、基础设施卸载、以太网交换仍然是 NVL72 能作为工厂砖块的原因。第七颗 Groq 3 LPU 被公开写成推理加速路径、可单独成柜，与 72 个 Rubin GPU 并行存在，而不是把 NVL72 改成「72 GPU + 若干 LPU 混在同一 NVLink 域」。2026 年平台材料还提到多种专用架协同（计算、以太网光子交换、存储、LPU），目标叙事是 agentic 工作负载：预训练、后训练、测试时扩展、在线推理。对算法工程师，这意味着调度器可能看到异构柜型；对容量模型，必须按柜型分别记账，不能用单一「Rubin PFLOPS」加总所有架。</p><p>液冷、无缆托盘、热插拔交换属于平台运维合同：安装与维修按柜级窗口写。部分填充机柜仍可运行等语句出现在公开材料里时，把它当成可用性设计，而不是可以在半通域上继续跑 64 路 TP。集群应能把整柜从副本集摘掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>平台成立，靠的是流量语义在六（或七）颗芯片之间预先对齐：NVLink 上的集合、网卡上的拥塞与隔离、DPU 上的存储与证明、以太交换上的公平性，不是集成商现场「调通」。Scale-Up 与 Scale-Out 的速率可以差一个数量级，所以并行维必须分层——这一点机柜篇已写。平台机制多出来的是：<strong>复制</strong>：用同一份 BOM 复制许多 NVL72，用同一套 Spectrum-X / IB 配方把它们连成工厂，用同一套 DOCA 策略管租户。没有这一层，超节点只是实验室里的一台大机器。</p><p>HBM4、第三代 Transformer Engine、NVFP4 属于 Rubin GPU 执行层，细节见 <a href="/llm/rubin-gpu-hbm4">Rubin GPU</a>。平台不改 MMA 数学，但决定推理 KV 能否卸到 CPU / 存储柜、训练梯度同步走哪张网、机密计算是否覆盖 NVLink。agent 控制面放在 Vera CPU 上，是平台对「推理不只是 GEMM」的分工：token 生成在 GPU，工具调用与编排在 CPU，长上下文可能在存储架。这些角色是公开叙事，具体延迟以编程指南与基准为准。</p><p><span class="marginnote">Vera CPU 与 Rubin GPU 经 NVLink-C2C 的一致性模型以超芯文档为准。平台文不发明「机柜级 malloc」。CPU 内存是第二层，不是 72 份 HBM 的自动延伸。</span></p><h3 id="与-blackwell-nvl72-的同构、以及不要抄的差" tabindex="-1">与 Blackwell NVL72 的同构、以及不要抄的差 <a class="header-anchor" href="#与-blackwell-nvl72-的同构、以及不要抄的差" aria-label="Permalink to &quot;与 Blackwell NVL72 的同构、以及不要抄的差&quot;">​</a></h3><p>GB200 NVL72 已经把「72 GPU 一域」产品化。Vera Rubin NVL72 保持同构：计算托盘 + 交换托盘、柜外 SuperNIC、液冷。换代的是芯片代数与共设计范围（网卡、DPU、以太交换、CPU 一并换代），不是把域改成 128。因此软件迁移的第一约束仍是：通信子是否整柜、HBM 是否按相加规划、调度是否认域。第二约束才是 NVFP4、HBM4、NVLink 6 的新能力。把 Rubin 平台当成「只能跑新模型」是错的；当成「可以继续按 8 卡副本切」也是错的。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用 NVL72 取消 Scale-Out。不要把 LPU 柜、存储柜的公开吞吐加进 GPU 柜的 MFU。不要填写未出现在 NVIDIA 文档里的铜缆单通道速率或未公布的背板表。操作系统与 Kubernetes 若只懂 8 卡 Pod，会把平台切碎，需要拓扑管理器。Confidential computing 改变多租户上能否放受保护权重，与峰值 FLOPS 无关，但与云上卖点有关——不要在关闭 TEE 的自建机房里假设同一隔离级别。</p><p>厂商「一柜顶上一代若干柜」依赖指定工作负载。自己的验收仍是：域内 NCCL 微基准、跨柜 DP 带宽、检查点是否走 DPU、故障时能否整柜摘除。平台是产品与运维单位；逻辑加速器是编程单位。两句话都要写进设计文档。</p><p><span class="marginnote">出处：NVIDIA 新闻稿 <em>NVIDIA Vera Rubin Opens Agentic AI Frontier</em> 与 Vera Rubin NVL72 产品叙述；技术博客 <em>Inside the NVIDIA Vera Rubin Platform: Six New Chips, One AI Supercomputer</em>。七芯片与 POD 级机柜以 2026 年公开更新为准，并与六芯片计算柜分开记账。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Vera Rubin 平台 = NVL72 计算柜 + 共设计的 Scale-Out 网、DPU 基础设施与以太网交换，可复制成工厂。</li><li>NVLink 域仍停在柜内 72 GPU；多柜靠 IB / Spectrum-X，不把 NVLink 乘大。</li><li>六芯片分工仍是计算柜的骨架；Groq 3 LPU 等是后补推理路径，不计入 72。</li><li>安全、存储、多租户在 DPU / DOCA 平面；训练通信不要与检查点抢 NVLink。</li><li>营销加速比与未公开背板速率不进入容量表。</li><li>出处：NVIDIA Vera Rubin 平台与 NVL72 公开材料；机柜编程模型见 <a href="/llm/vera-rubin-nvl72">NVL72</a>，芯片分工见 <a href="/llm/rubin-six-chips">六芯片</a>。</li></ul>',15))])}const b=l(V,[["render",c]]);export{h as __pageData,b as default};
